files.server.test.ts:
import { createFakePluginHost } from "@bb/plugin-sdk/testing";
import { describe, expect, it } from "vitest";

import plugin from "./server";

describe("Scaffold Upgrade plugin", () => {
  it("loads through the bb plugin harness", async () => {
    const { bb, harness } = createFakePluginHost({ pluginId: "scaffold-upgrade" });
    plugin(bb);
    expect(harness.inspection.logEntries.at(-1)?.message).toBe("Scaffold Upgrade loaded");
    await harness.lifecycle.dispose();
  });
});
